package pillar.templateregistry.upgrade
import org.junit.jupiter.api.*; import org.junit.jupiter.api.Assertions.*
class UpgradeStateMachineTest { val sm=UpgradeStateMachine(); @Test fun allowed(){ var s=UpgradeState.announce; s=sm.transition(s,UpgradeState.stage,Approval("a")); s=sm.transition(s,UpgradeState.dual_publish,Approval("a","b"),true); s=sm.transition(s,UpgradeState.cutover,Approval("a","b"),true); assertEquals(UpgradeState.retire, sm.transition(s,UpgradeState.retire,Approval("a","b"),true)) } @Test fun blocked(){ assertThrows(IllegalStateException::class.java){ sm.transition(UpgradeState.announce,UpgradeState.cutover,Approval("a")) } } @Test fun dualControl(){ assertThrows(IllegalStateException::class.java){ sm.transition(UpgradeState.stage,UpgradeState.dual_publish,Approval("a"),true) } } @Test fun rollback(){ assertEquals(UpgradeState.rolled_back, sm.transition(UpgradeState.stage,UpgradeState.rolled_back,Approval("a"))) } }
